PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS registry_schema_version (version TEXT PRIMARY KEY, installed_at TEXT NOT NULL, description TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS cosmic_domain (domain_code TEXT PRIMARY KEY, name_zh TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS registry_entity_type (type_code TEXT PRIMARY KEY, name_zh TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS registry_license_policy (policy_id TEXT PRIMARY KEY, license TEXT NOT NULL, redistribution_allowed INTEGER CHECK(redistribution_allowed IN (0,1)), ml_training_allowed INTEGER CHECK(ml_training_allowed IN (0,1)), commercial_use_allowed INTEGER CHECK(commercial_use_allowed IN (0,1)), retention_rule TEXT NOT NULL, assessed_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS registry_source (source_id TEXT PRIMARY KEY, publisher TEXT NOT NULL, source_type TEXT NOT NULL, canonical_uri TEXT NOT NULL UNIQUE, access_class TEXT NOT NULL CHECK(access_class IN ('PUBLIC','RESTRICTED')), publication_date TEXT, retrieved_at TEXT NOT NULL, content_hash TEXT, policy_id TEXT NOT NULL REFERENCES registry_license_policy(policy_id), verification_scope TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS registry_dataset (dataset_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES registry_source(source_id), dataset_version TEXT NOT NULL, file_sha256 TEXT NOT NULL, row_count INTEGER NOT NULL CHECK(row_count>=0), imported_at TEXT NOT NULL, UNIQUE(source_id,dataset_version,file_sha256)) STRICT;
CREATE TABLE IF NOT EXISTS registry_entity (entity_id TEXT PRIMARY KEY CHECK(entity_id GLOB 'DUECG-EID::*'), entity_type TEXT NOT NULL REFERENCES registry_entity_type(type_code), canonical_name TEXT NOT NULL, world_domain TEXT NOT NULL CHECK(world_domain IN ('HISTORY','REAL-TWIN','SIM','FICTION')), status TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_entity_alias (alias_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), alias TEXT NOT NULL, language_tag TEXT NOT NULL, alias_kind TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from), UNIQUE(entity_id,alias,language_tag,valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS bridge_entity_external_id (bridge_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), id_system TEXT NOT NULL, external_id TEXT NOT NULL, external_version TEXT NOT NULL, match_method TEXT NOT NULL, match_score REAL CHECK(match_score BETWEEN 0 AND 1), review_status TEXT NOT NULL CHECK(review_status IN ('ACCEPTED','PENDING','REJECTED')), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from), UNIQUE(id_system,external_id,external_version,valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_external_id (external_key TEXT PRIMARY KEY, id_system TEXT NOT NULL, external_id TEXT NOT NULL, external_version TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from), UNIQUE(id_system,external_id,external_version,valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_entity_relation (relation_id TEXT PRIMARY KEY, subject_entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), predicate TEXT NOT NULL, object_entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_entity_status_history (history_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), status TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_claim (claim_id TEXT PRIMARY KEY, subject_entity_id TEXT REFERENCES registry_entity(entity_id), predicate TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), confidence REAL CHECK(confidence BETWEEN 0 AND 1), claim_status TEXT NOT NULL CHECK(claim_status IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_observation (observation_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), metric_id TEXT NOT NULL, value REAL, unit TEXT NOT NULL, sample_n INTEGER CHECK(sample_n>=0), uncertainty REAL CHECK(uncertainty>=0), method_id TEXT NOT NULL, claim_id TEXT REFERENCES registry_claim(claim_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_evidence_link (evidence_link_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES registry_claim(claim_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), observation_id TEXT REFERENCES registry_observation(observation_id), direction TEXT NOT NULL CHECK(direction IN ('SUPPORTS','CONTRADICTS','CONTEXT')), locator TEXT NOT NULL, transaction_time TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS registry_spatial_frame (frame_id TEXT PRIMARY KEY, cosmic_domain TEXT NOT NULL REFERENCES cosmic_domain(domain_code), center_name TEXT NOT NULL, axis_definition TEXT NOT NULL, position_unit TEXT NOT NULL, velocity_unit TEXT, reference_uri TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS registry_entity_location (location_observation_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), cosmic_domain TEXT NOT NULL REFERENCES cosmic_domain(domain_code), spatial_frame TEXT NOT NULL REFERENCES registry_spatial_frame(frame_id), central_body TEXT NOT NULL, epoch TEXT NOT NULL, time_scale TEXT NOT NULL CHECK(time_scale IN ('UTC','TAI','TT','TDB','TCB','SIM_TIME')), geometry_ref TEXT, x REAL, y REAL, z REAL, vx REAL, vy REAL, vz REAL, position_unit TEXT NOT NULL, velocity_unit TEXT, uncertainty_ref TEXT, source_solution TEXT NOT NULL, disclosure_precision TEXT NOT NULL CHECK(disclosure_precision IN ('PUBLIC_GENERAL','PUBLIC_PRECISE','REDACTED')), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from), CHECK((x IS NULL AND y IS NULL AND z IS NULL) OR (x IS NOT NULL AND y IS NOT NULL AND z IS NOT NULL)), CHECK((vx IS NULL AND vy IS NULL AND vz IS NULL) OR (vx IS NOT NULL AND vy IS NOT NULL AND vz IS NOT NULL)), CHECK(evidence_state NOT IN ('UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED') OR (x IS NULL AND y IS NULL AND z IS NULL AND geometry_ref IS NULL AND vx IS NULL AND vy IS NULL AND vz IS NULL)), CHECK(disclosure_precision != 'REDACTED' OR (x IS NULL AND y IS NULL AND z IS NULL AND geometry_ref IS NULL AND vx IS NULL AND vy IS NULL AND vz IS NULL))) STRICT;
CREATE TABLE IF NOT EXISTS registry_country_area (entity_id TEXT PRIMARY KEY REFERENCES registry_entity(entity_id), iso_alpha2 TEXT NOT NULL UNIQUE, iso_alpha3 TEXT NOT NULL UNIQUE, iso_numeric TEXT NOT NULL, un_m49_code TEXT, calling_code TEXT, baseline_json TEXT NOT NULL CHECK(json_valid(baseline_json)), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_admin_unit (entity_id TEXT PRIMARY KEY REFERENCES registry_entity(entity_id), subdivision_code TEXT NOT NULL UNIQUE, country_entity_id TEXT NOT NULL REFERENCES registry_country_area(entity_id), name TEXT NOT NULL, unit_type TEXT NOT NULL, parent_entity_id TEXT REFERENCES registry_admin_unit(entity_id), baseline_json TEXT NOT NULL CHECK(json_valid(baseline_json)), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_settlement (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), settlement_kind TEXT NOT NULL, country_entity_id TEXT REFERENCES registry_country_area(entity_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_legal_entity (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), jurisdiction_entity_id TEXT REFERENCES registry_country_area(entity_id), legal_form TEXT, registration_status TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_public_body (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), jurisdiction_entity_id TEXT REFERENCES registry_country_area(entity_id), mandate TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_research_org (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), org_kind TEXT NOT NULL, research_scope TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_public_facility (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), facility_kind TEXT NOT NULL, public_acknowledgment_uri TEXT NOT NULL, operator_entity_id TEXT REFERENCES registry_entity(entity_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from), UNIQUE(entity_id)) STRICT;
CREATE TABLE IF NOT EXISTS registry_infrastructure (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), infrastructure_kind TEXT NOT NULL, operator_entity_id TEXT REFERENCES registry_entity(entity_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_person_public_role (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), person_entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), organization_entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), role_title TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_space_org (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), org_role TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_space_program (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), lead_entity_id TEXT REFERENCES registry_entity(entity_id), program_status TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_space_mission (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), program_entity_id TEXT REFERENCES registry_entity(entity_id), mission_status TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_space_asset (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), asset_kind TEXT NOT NULL, mission_entity_id TEXT REFERENCES registry_entity(entity_id), operational_status TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_space_vehicle (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), vehicle_kind TEXT NOT NULL, operational_status TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_ground_facility_public (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), facility_entity_id TEXT NOT NULL REFERENCES registry_public_facility(entity_id), service_kind TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_space_research_output (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), title TEXT NOT NULL, doi TEXT, organization_entity_id TEXT REFERENCES registry_entity(entity_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_celestial_object (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), object_kind TEXT NOT NULL, catalog_solution TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_ephemeris_solution (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), frame_id TEXT NOT NULL REFERENCES registry_spatial_frame(frame_id), epoch TEXT NOT NULL, time_scale TEXT NOT NULL, position_unit TEXT NOT NULL, velocity_unit TEXT NOT NULL, solution_version TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_astrobiology_evidence (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), evidence_kind TEXT NOT NULL, finding_status TEXT NOT NULL, claim_id TEXT NOT NULL REFERENCES registry_claim(claim_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_virtual_world (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), engine_name TEXT NOT NULL, engine_version TEXT NOT NULL, local_frame TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from), UNIQUE(entity_id)) STRICT;
CREATE TABLE IF NOT EXISTS registry_virtual_entity (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), virtual_world_entity_id TEXT NOT NULL REFERENCES registry_virtual_world(entity_id), source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_simulation_run (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), virtual_world_entity_id TEXT REFERENCES registry_virtual_world(entity_id), model_version TEXT NOT NULL, random_seed TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS registry_synthetic_population (record_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES registry_entity(entity_id), simulation_run_id TEXT NOT NULL REFERENCES registry_simulation_run(record_id), population_count INTEGER NOT NULL CHECK(population_count>=0), generation_method TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES registry_source(source_id), evidence_state TEXT NOT NULL CHECK(evidence_state IN ('VERIFIED','OBSERVED','INFERRED','CLAIMED','UNKNOWN','REDACTED','RESTRICTED_NOT_INGESTED')), valid_from TEXT NOT NULL, valid_to TEXT, transaction_time TEXT NOT NULL, CHECK(valid_to IS NULL OR valid_to > valid_from)) STRICT;
CREATE TABLE IF NOT EXISTS staging_service_catalogue (catalogue_id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, verification_status TEXT NOT NULL CHECK(verification_status IN ('V','P','U')), verification_url TEXT, verified_scope TEXT NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), dataset_id TEXT NOT NULL REFERENCES registry_dataset(dataset_id), candidate_entity_id TEXT REFERENCES registry_entity(entity_id), resolution_status TEXT NOT NULL CHECK(resolution_status IN ('PENDING','ACCEPTED','REJECTED')), transaction_time TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS registry_ingest_record (ingest_id TEXT PRIMARY KEY, entity_id TEXT REFERENCES registry_entity(entity_id), dataset_id TEXT NOT NULL REFERENCES registry_dataset(dataset_id), external_key TEXT NOT NULL, record_payload TEXT NOT NULL CHECK(json_valid(record_payload)), transform_version TEXT NOT NULL, transaction_time TEXT NOT NULL, UNIQUE(dataset_id,external_key)) STRICT;
CREATE TABLE IF NOT EXISTS registry_coverage (coverage_id TEXT PRIMARY KEY, country_entity_id TEXT NOT NULL REFERENCES registry_country_area(entity_id), layer TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('BASELINE','TO_RESOLVE','VERIFIED')), numerator INTEGER CHECK(numerator>=0), denominator INTEGER CHECK(denominator>=0), source_id TEXT NOT NULL REFERENCES registry_source(source_id), gap_reason TEXT NOT NULL, transaction_time TEXT NOT NULL, UNIQUE(country_entity_id,layer)) STRICT;
CREATE TABLE IF NOT EXISTS registry_adapter_contract (adapter_id TEXT PRIMARY KEY, id_system TEXT NOT NULL, canonical_uri TEXT NOT NULL, target_table TEXT NOT NULL, version_required INTEGER NOT NULL CHECK(version_required IN (0,1)), status TEXT NOT NULL CHECK(status IN ('LOCAL_IMPORTED','INTERFACE_ONLY','BLOCKED')), license_review TEXT NOT NULL, notes TEXT NOT NULL) STRICT;
