CREATE VIEW IF NOT EXISTS space_organization AS SELECT * FROM registry_space_org;
CREATE VIEW IF NOT EXISTS space_program AS SELECT * FROM registry_space_program;
CREATE VIEW IF NOT EXISTS space_mission AS SELECT * FROM registry_space_mission;
CREATE VIEW IF NOT EXISTS space_vehicle AS SELECT * FROM registry_space_vehicle;
CREATE VIEW IF NOT EXISTS space_object AS SELECT * FROM registry_space_asset;
CREATE VIEW IF NOT EXISTS space_facility_public AS SELECT * FROM registry_ground_facility_public;
CREATE VIEW IF NOT EXISTS space_research_output AS SELECT * FROM registry_space_research_output;
CREATE VIEW IF NOT EXISTS registry_relation AS SELECT * FROM registry_entity_relation;
CREATE VIEW IF NOT EXISTS v_country_admin AS SELECT c.iso_alpha2,c.iso_alpha3,c.entity_id AS country_entity_id,a.entity_id AS admin_entity_id,a.subdivision_code,a.name,a.parent_entity_id,a.evidence_state FROM registry_country_area c LEFT JOIN registry_admin_unit a ON a.country_entity_id=c.entity_id;
CREATE VIEW IF NOT EXISTS v_model_features_approved AS SELECT o.observation_id,o.entity_id,o.metric_id,o.value,o.unit,o.valid_from,o.valid_to,o.transaction_time,o.source_id,o.uncertainty FROM registry_observation o JOIN registry_entity e USING(entity_id) JOIN registry_source s ON s.source_id=o.source_id JOIN registry_license_policy p ON p.policy_id=s.policy_id WHERE e.world_domain='REAL-TWIN' AND o.evidence_state IN ('VERIFIED','OBSERVED') AND o.value IS NOT NULL AND o.method_id!='UNKNOWN' AND p.ml_training_allowed=1 AND s.access_class='PUBLIC';
CREATE TRIGGER IF NOT EXISTS eid_format_insert BEFORE INSERT ON registry_entity BEGIN SELECT CASE WHEN length(NEW.entity_id)!=47 OR substr(NEW.entity_id,1,11)!='DUECG-EID::' OR substr(NEW.entity_id,26,1)!='7' OR substr(NEW.entity_id,31,1) NOT IN ('8','9','a','b') OR length(replace(substr(NEW.entity_id,12),'-',''))!=32 OR replace(substr(NEW.entity_id,12),'-','') GLOB '*[^0-9a-f]*' THEN RAISE(ABORT,'invalid UUIDv7 entity ID') END; END;
CREATE TRIGGER IF NOT EXISTS location_frame_insert BEFORE INSERT ON registry_entity_location BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM registry_spatial_frame f WHERE f.frame_id=NEW.spatial_frame AND f.cosmic_domain=NEW.cosmic_domain AND f.center_name=NEW.central_body AND f.position_unit=NEW.position_unit AND f.velocity_unit IS NEW.velocity_unit) THEN RAISE(ABORT,'frame/domain/center/unit mismatch') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM registry_entity e WHERE e.entity_id=NEW.entity_id AND ((e.world_domain IN ('SIM','FICTION') AND NEW.cosmic_domain!='VIRTUAL_LOCAL') OR (e.world_domain='REAL-TWIN' AND NEW.cosmic_domain='VIRTUAL_LOCAL'))) THEN RAISE(ABORT,'world/cosmic domain mismatch') END; END;
CREATE TRIGGER IF NOT EXISTS eid_format_update BEFORE UPDATE ON registry_entity BEGIN SELECT CASE WHEN length(NEW.entity_id)!=47 OR substr(NEW.entity_id,1,11)!='DUECG-EID::' OR substr(NEW.entity_id,26,1)!='7' OR substr(NEW.entity_id,31,1) NOT IN ('8','9','a','b') OR length(replace(substr(NEW.entity_id,12),'-',''))!=32 OR replace(substr(NEW.entity_id,12),'-','') GLOB '*[^0-9a-f]*' THEN RAISE(ABORT,'invalid UUIDv7 entity ID') END; END;
CREATE TRIGGER IF NOT EXISTS location_frame_update BEFORE UPDATE ON registry_entity_location BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM registry_spatial_frame f WHERE f.frame_id=NEW.spatial_frame AND f.cosmic_domain=NEW.cosmic_domain AND f.center_name=NEW.central_body AND f.position_unit=NEW.position_unit AND f.velocity_unit IS NEW.velocity_unit) THEN RAISE(ABORT,'frame/domain/center/unit mismatch') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM registry_entity e WHERE e.entity_id=NEW.entity_id AND ((e.world_domain IN ('SIM','FICTION') AND NEW.cosmic_domain!='VIRTUAL_LOCAL') OR (e.world_domain='REAL-TWIN' AND NEW.cosmic_domain='VIRTUAL_LOCAL'))) THEN RAISE(ABORT,'world/cosmic domain mismatch') END; END;
